package cli

import (
	"fmt"
	"net"
	"strings"

	"opnsense-cli/opnsense/api/interfaces"
)

// /interface/neighbor: Interfaces > Neighbors (api/interfaces/neighbor_settings), static ARP (IPv4) and NDP
// (IPv6) entries. Items are selected by the # of print, the uuid, the address, the MAC address or the
// description. Entries with another origin than manual are generated by OPNsense (e.g. from DHCP reservations)
// and can not be changed here

func interfaceNeighborValidateMAC(value string) error {
	if value == "" {
		return nil
	}
	if hardware, err := net.ParseMAC(value); err != nil || len(hardware) != 6 {
		return fmt.Errorf("must be a MAC address like aa:bb:cc:dd:ee:ff, got %q", value)
	}
	return nil
}

func init() {
	var spec = &interfaceSpec{
		path:     "interface/neighbor",
		help:     "static ARP and NDP entries (Interfaces > Neighbors)",
		kind:     interfaces.Neighbors,
		itemHelp: "the #, uuid, address, MAC address or description of the neighbor",
		fields: []interfaceField{
			{Arg: Arg{Name: "address", Required: true, Help: "the IPv4 (ARP) or IPv6 (NDP) address", Validate: ValidateIP}, api: "ipaddress"},
			{Arg: Arg{Name: "mac-address", Required: true, Help: "the MAC address like aa:bb:cc:dd:ee:ff", Validate: interfaceNeighborValidateMAC},
				api: "etheraddr"},
			interfaceDescription("descr"),
		},
		names: func(item interfaces.Item) []string {
			return []string{item.Get("ipaddress"), item.Get("etheraddr"), item.Get("descr")}
		},
		keyArgs: []string{"address"},
		keyMatch: func(item interfaces.Item, fields map[string]string) bool {
			return strings.EqualFold(item.Get("ipaddress"), fields["ipaddress"])
		},
		printLong: `ORIGIN is manual for configured entries, other entries are generated by OPNsense (e.g. from DHCP
reservations) and can not be changed here.`,
		addLong: `address and mac-address are required. If a neighbor with this address exists, add fails unless replace is
given, then that neighbor is replaced completely.

  add address=192.168.1.20 mac-address=00:11:22:33:44:55 description=printer`,
		apply: interfaceApplySpec{
			help: "apply the neighbor changes: set the static ARP/NDP entries, remove deleted ones",
		},
	}
	spec.columns = []interfaceColumn{
		interfaceFieldColumn("ADDRESS", spec, "address"),
		interfaceFieldColumn("MAC-ADDRESS", spec, "mac-address"),
		{header: "ORIGIN", value: func(item interfaces.Item) string { return item.Get("origin") }},
		interfaceFieldColumn("DESCRIPTION", spec, "description"),
	}
	interfaceRegister(spec)
}
